// Define constants
const float PI = 3.14159265;
const vec3 SCLERA_COLOR = vec3(0.81, 0.8, 0.8);
const float SCLERA_SIZE = 0.75;
const vec3 IRIS_COLOR = vec3(0.12, 0.57, 0.82);
const float IRIS_SIZE = 0.5;
const vec3 PUPIL_COLOR = vec3(0.0, 0.0, 0.0);
const float PUPIL_SIZE = 0.19;
const float ARC_LIGHT_INTENSITY = 0.5;
const float ARC_DARK_INTENSITY = 0.6;

// Function to convert a vector to an angle
float VectorConvertedToAngle(vec2 uv, float tiling) {
    return fract(atan(uv.y, uv.x) / (2.0 * PI) * tiling);
}

// Function to interpolate between two values
float InverseLerp(float a, float b, float alpha) {
    return (alpha - a) / (b - a);
}

// Function to draw a circle
float Circle(vec2 uv, float radius) {
    return length(uv) - radius;
}

// Function to draw a Triangle
float Triangle( in vec2 p, in float r )
{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0*r, 0.0 );
    return -length(p)*sign(p.y);
}

// Function to get a sharp binary value from an SDF
float SharpFromSDF(float shape) {
    return step(0.0, shape);
}

// Function to get a gradient between two SDFs
float GradientBetweenSDF(float a, float b) {
    return InverseLerp(a, b, 0.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize screen coordinates
    vec2 global_uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 2.0;

    // Eye uv
    vec2 uv = global_uv;
    uv.x += sin(iTime*0.2)*0.3;

    // Generate SDFs for different parts of the eye
    float sclera = Circle(uv, SCLERA_SIZE);
    float iris = Circle(uv, IRIS_SIZE);

    float triangle_pupil = Triangle(uv, PUPIL_SIZE);
    float circle_pupil = Circle(uv, PUPIL_SIZE);
    float pupil = mix(triangle_pupil, circle_pupil, (sin(iTime)+1.0)/2.0);

    // Calculate gradients
    float gradient_pupil_iris = GradientBetweenSDF(pupil, iris);

    // Calculate UV coordinates for the iris texture
    float iris_x_uv = gradient_pupil_iris;
    float iris_y_uv = VectorConvertedToAngle(uv, 2.0);
    vec2 iris_uv = vec2(iris_x_uv, iris_y_uv);

    // Sample the iris texture and adjust contrast
    float iris_texture = texture(iChannel0, iris_uv).x;
    float contrast_factor = 3.0;
    iris_texture = clamp(((iris_texture - 0.5) * contrast_factor + 0.5), 0.0, 1.0);
    vec3 iris_color = mix(IRIS_COLOR * 1.5, IRIS_COLOR * 0.5, iris_texture);

    // Calculate pupil color
    float sharp_pupil = SharpFromSDF(pupil);
    float pupil_mask = sharp_pupil * smoothstep(0.0, 0.1, gradient_pupil_iris);
    vec3 pupil_color = (1.0 - pupil_mask) * PUPIL_COLOR;

    // Calculate sclera mask
    float sclera_mask = smoothstep(-0.04, 0.04, iris);
    float sclera_color_mask = clamp(Circle(uv, 0.9), 0.0, 1.0);
    vec3 sclera_color = mix(SCLERA_COLOR,vec3(0.67,0.44,0.39),sclera_color_mask);

    // Calculate limbus
    float limbus = clamp(pow(clamp(abs(iris) / 0.05, 0.0, 1.0), 1.2) + 0.4, 0.0, 1.0);

    // Calculate lighting
    vec3 iris_normal = normalize(vec3(uv.x * -4.0, uv.y * -4.0, 0.5));
    vec3 normal = mix(iris_normal, vec3(0.5, 0.5, 1.0), SharpFromSDF(iris));
    float arc_light = max(1.0, smoothstep(0.0, 1.0, normal.y) + ARC_LIGHT_INTENSITY);
    float arc_dark = 1.0 - clamp(smoothstep(0.0, 1.0, normal.y * -1.0) - (1.0-ARC_DARK_INTENSITY), 0.0, 1.0);

    // Apply lighting to iris color
    iris_color *= arc_light;
    iris_color *= arc_dark;

    // Combine eye colors
    vec3 eye_color = mix(pupil_color, iris_color, pupil_mask);
    vec3 mix_sclera = mix(eye_color, sclera_color, sclera_mask);
    mix_sclera *= limbus;

    // Sample reflection
    vec3 reflectedColor = texture(iChannel1, vec3(global_uv, normal.z)).rgb;

    // Adjust reflection intensity
    float mix_reflection_intensity = mix(2.0, 25.0, sclera_mask);
    mix_sclera += reflectedColor / mix_reflection_intensity;

    // Output final color
    fragColor = vec4(mix_sclera, 1.0);
}
